mapper.select:
SELECT R.RESERVATION_ID, R.RESERVATION_NO, R.REQUEST_ID, R.STATUS, R.PAY_STATUS, R.MOVE_DATE, R.MOVE_TIME, R.MOVE_MEMO,
       R.APPLIED_AT, R.DEPOSIT_PAID_AT, R.CANCELLED_AT, R.CANCELLED_BY
  FROM TBL_RESERVATION R
  JOIN TBL_MOVE_REQUEST M ON M.REQUEST_ID = R.REQUEST_ID
 WHERE R.RESERVATION_ID = #{reservationId}
   AND M.MEMBER_ID = #{memberId}

mapper.update:
UPDATE TBL_RESERVATION
   SET MOVE_MEMO = #{memo}
 WHERE RESERVATION_ID = #{reservationId}
   AND STATUS = '01'

UPDATE TBL_RESERVATION
   SET MOVE_DATE = #{moveDate},
       MOVE_TIME = #{moveTime}
 WHERE RESERVATION_ID = #{reservationId}
   AND STATUS = '01'
